/**
 * The skill-tool entity's sub-type table. Skill tools are a real sub-entity —
 * six terraform resource types sharing one ownership shape (skill_id +
 * name/description/status) — so per-sub-type knowledge is one ROW here,
 * exactly like `entities/agent-tool/types.ts` (which this mirrors).
 *
 * Search-table support stays coupled to the underlying AI search-table graph
 * module; every other provider skill-tool resource is implemented end to end.
 *
 * Note the wire key for the automation tool is `automation`, not agent-tool's
 * `executeWorkflow` — confirmed against the live provider schema
 * (`entities/skill/tools.ts`'s `skillAutomation` factory).
 */
/** One skill-tool sub-type: authoring variant key ↔ resource type. */
export interface SkillToolSubType {
    /** The `AgenticSkillToolCreateInput` variant key — the tool factory's discriminant ("createRecord"). */
    readonly typeKey: string;
    /** Terraform resource type ("elementum_agentic_skill_create_record_tool"). */
    readonly resourceType: string;
    /** Implemented on the terraform path (to-tf + from-tf + printer). */
    readonly implemented?: true;
}
export declare const SKILL_TOOL_SUB_TYPES: readonly SkillToolSubType[];
export declare const SKILL_TOOL_SUB_TYPE_BY_TYPE_KEY: ReadonlyMap<string, SkillToolSubType>;
export declare const SKILL_TOOL_SUB_TYPE_BY_RESOURCE: ReadonlyMap<string, SkillToolSubType>;
/** The resource types the terraform path round-trips today (adoption scope). */
export declare const IMPLEMENTED_SKILL_TOOL_RESOURCE_TYPES: readonly string[];
/** Every declared skill-tool resource type — stream partition recognizes these by name. */
export declare const ALL_SKILL_TOOL_RESOURCE_TYPES: readonly string[];
/**
 * Attributes `skillToolFromTf` understands per implemented sub-type — growth
 * is reported loudly. Shared permissions (`run_as` and
 * `service_account_id`) are included in every implemented row so pull never
 * drops a tool's execution identity.
 */
export declare const KNOWN_SKILL_TOOL_ATTRS: Readonly<Record<string, ReadonlySet<string>>>;
/** Known provider attrs with no authoring slot yet — reported by name, tool still pulled. */
export declare const UNAUTHORABLE_SKILL_TOOL_ATTRS: ReadonlySet<string>;
